    [4909]={name="Kodo Hunter's Leggings",quality=2,ilvl=15,sourceType="quest_reward",instructions="Reward from the quest 'Rites of the Earthmother'. In Mulgore.",zone="Mulgore",questName="Rites of the Earthmother",lore="We are hunters. Down below in Mulgore there is a mighty kodo named Arra'chea."},
