    [5016]={name="Artisan's Trousers",quality=2,ilvl=35,sourceType="quest_reward",instructions="Reward from the quest 'Jarl Needs a Blade'. In Dustwallow Marsh.",zone="Dustwallow Marsh",questName="Jarl Needs a Blade",lore="I have cutting to do. I can't tell you what I'm going to cut, but... I need myself a blade. A certain blade... Some people call it a sword. I call it a swing blade."},
