    [9397]={name="Energy Cloak",quality=3,ilvl=39,reqLevel=34,sourceType="world_drop",instructions="World drop - drops from 28 creature types around level 35-40. Also found on the auction house.",proc="Use: Restores 390 to 410 mana. (1 Hour Cooldown)"},
    [9449]={name="Manual Crowd Pummeler",quality=3,ilvl=34,reqLevel=28,sourceType="boss_drop",instructions="Drops from Crowd Pummeler 9-60 in Gnomeregan.",zone="Gnomeregan",npc="Crowd Pummeler 9-60",lore="A Gnomeregan oddity whose Use effect grants a huge burst of attack speed. Feral druids kept it for that alone, because it works in cat form -- and it has limited charges, so every use is a decision.",proc="Use: Increases your haste rating by 500 for 30 sec."},
    [9455]={name="Emissary Cuffs",quality=3,ilvl=33,reqLevel=28,sourceType="boss_drop",instructions="Drops from Dark Iron Ambassador in Gnomeregan.",zone="Gnomeregan",npc="Dark Iron Ambassador"},
    [9461]={name="Charged Gear",quality=3,ilvl=37,reqLevel=28,sourceType="boss_drop",instructions="Drops from Mekgineer Thermaplugg in Gnomeregan.",zone="Gnomeregan",npc="Mekgineer Thermaplugg"},
    [9482]={name="Witch Doctor's Cane",quality=3,ilvl=47,reqLevel=42,sourceType="world_drop",instructions="World drop - drops from 15 creature types around level 44-46. Also found on the auction house."},
    [9527]={name="Spellshifter Rod",quality=2,ilvl=46,sourceType="quest_reward",instructions="Reward from the quest 'Tiara of the Deep'. In Zul'Farrak.",zone="Zul'Farrak",questName="Tiara of the Deep",lore="Long ago I possessed a beautiful piece of jewelry, the Tiara of the Deep. And not only was it pretty--it held great power for those with the knowledge to use it."},
    [9631]={name="Pratt's Handcrafted Gloves",quality=2,ilvl=45,sourceType="quest_reward",instructions="Reward from the quest 'The Mark of Quality' - pick it over the other choices. In Feralas.",zone="Feralas",questName="The Mark of Quality",lore="My philosophy on leatherworking is that the work must be the best quality possible - no compromises. Anyone who says that quality doesn't matter is trying to sell you ocean-front property in Dun Morogh!"},
    [9632]={name="Jangdor's Handcrafted Gloves",quality=2,ilvl=45,sourceType="quest_reward",instructions="Reward from the quest 'The Mark of Quality' - pick it over the other choices. In Feralas.",zone="Feralas",questName="The Mark of Quality",lore="I take pride in my leather work, and I feel it shows; quality should never be compromised. Anyone who says that quality doesn't matter would also have you believe that the earth does not keep secrets!"},
    [9636]={name="Swashbuckler Sash",quality=2,ilvl=45,sourceType="quest_reward",instructions="Reward from the quest 'Deliver to MacKinley' - pick it over the other choices. In Tanaris.",zone="Tanaris",questName="Deliver to MacKinley",lore="Thanks again for your help. Here's a bottle of Steamwheedle bilge rum. Take it to MacKinley and he can finally put to rest his crazy beliefs about Booty Bay booze."},
    [9642]={name="Band of the Great Tortoise",quality=2,ilvl=50,sourceType="quest_reward",instructions="Reward from the quest 'Tooga's Quest' - pick it over the other choices. In Tanaris.",zone="Tanaris",questName="Tooga's Quest",lore="I am so lost! My wife, Torta, sent me out to fetch dinner and I must have taken a wrong turn somewhere. Would you be so kind as to lead me back to Torta?"},
    [9644]={name="Thermotastic Egg Timer",quality=2,ilvl=51,sourceType="quest_reward",instructions="Reward from the quest 'Rescue OOX-17/TN!' - pick it over the other choices. In Tanaris.",zone="Tanaris",questName="Rescue OOX-17/TN!",lore="The gnome's voice crackles once again from the robot: \"I need to move OOX-17/TN to an open, safe place so it can begin a lengthy take-off procedure."},
    [9647]={name="Failed Flying Experiment",quality=2,ilvl=48,sourceType="quest_reward",instructions="Reward from the quest 'Rescue OOX-22/FE!' - pick it over the other choices. In Feralas.",zone="Feralas",questName="Rescue OOX-22/FE!",lore="The gnome's voice crackles once again from the robot: \"I need to move OOX-22/FE to an open, safe place so it can begin a lengthy take-off procedure."},
    [9652]={name="Gryphon Rider's Leggings",quality=3,ilvl=53,sourceType="quest_reward",instructions="Reward from the quest 'Saving Sharpbeak' - pick it over the other choices. In The Hinterlands.",zone="The Hinterlands",questName="Saving Sharpbeak",lore="We must save Sharpbeak! Fight your way to the top of Jintha'Alor in the heart of Vilebranch territory, gain the key to Sharpbeak's cage from the vile Priestess Hexx, and then find and save Sharpbeak!"},
    [9683]={name="Strength of the Treant",quality=3,ilvl=51,sourceType="quest_reward",instructions="Reward from the quest 'Weapons of Spirit' - pick it over the other choices. In Feralas.",zone="Feralas",questName="Weapons of Spirit",lore="Imbuing the muisek into the weapons is a difficult process. Now that I have all of the required materials and the muisek of the creatures that you captured, I may begin."},
    [9699]={name="Garrison Cloak",quality=2,ilvl=33,sourceType="quest_reward",instructions="Reward from the quest 'Return to Vahlarriel' - pick it over the other choices. In Desolace.",zone="Desolace",questName="Return to Vahlarriel",lore="So, the time is now then? I appreciate your efforts, and if the situation does not lend itself, then allow me to thank you now for everything you've done for me and my family."},
