    [11193]={name="Blazewind Breastplate",quality=2,ilvl=57,sourceType="quest_reward",instructions="Reward from the quest 'Tremors of the Earth' - pick it over the other choices. In Badlands.",zone="Badlands",questName="Tremors of the Earth",lore="It has become obvious that we cannot ensure that Blacklash and Hematus will remain imprisoned in Lethlor."},
    [11262]={name="Orb of Lorica",quality=3,ilvl=44,sourceType="quest_reward",instructions="Reward from the quest 'In the Name of the Light' - pick it over the other choices. In Scarlet Monastery.",zone="Scarlet Monastery",questName="In the Name of the Light",lore="I once served the Scarlet Crusade with honor, loyalty and pride. I believed their cause to be a noble one: to rid Azeroth of the undead."},
