    [11853]={name="Rambling Boots",quality=2,ilvl=18,sourceType="quest_reward",instructions="Reward from the quest 'Stolen Silver' - pick it over the other choices. In The Barrens.",zone="The Barrens",questName="Stolen Silver",lore="You may have killed the raptors, but the silver they stole must be recovered! I have reports that the raptors have a large grouping of nests south of Ratchet, known as the Raptor Grounds."},
    [11855]={name="Tork Wrench",quality=2,ilvl=19,sourceType="quest_reward",instructions="Reward from the quest 'Samophlange Manual' - pick it over the other choices. In The Barrens.",zone="The Barrens",questName="Samophlange Manual",lore="I think I can fix the samophlange, but I'm going to need the user's manual first."},
    [11859]={name="Jademoon Orb",quality=2,ilvl=45,sourceType="quest_reward",instructions="Reward from the quest 'A Grim Discovery' - pick it over the other choices. In Feralas.",zone="Feralas",questName="A Grim Discovery",lore="What?! Ah, so I did mention a bounty, didn't I? Well, that'll teach me to open my mouth, won't it? You did the work, so I suppose it is only right you reap the greatest reward from it."},
    [11874]={name="Clouddrift Mantle",quality=2,ilvl=56,sourceType="quest_reward",instructions="Reward from the quest 'Ancient Spirit' - pick it over the other choices. In Felwood.",zone="Felwood",questName="Ancient Spirit",lore="Felwood was once a peaceful and serene land... Until the legion took hold. The infernals, destruction, chaos... The skull of Gul'dan ensured that none were spared here."},
    [11876]={name="Plainstalker Tunic",quality=2,ilvl=56,sourceType="quest_reward",instructions="Reward from the quest 'The Bait for Lar'korwi' - pick it over the other choices. In Un'Goro Crater.",zone="Un'Goro Crater",questName="The Bait for Lar'korwi",lore="This will be the most difficult part because there is some complexity to the plan. To the north of here, you will find a small trail into the mountains."},
    [11904]={name="Spirit of Aquementas",quality=2,ilvl=56,sourceType="quest_reward",instructions="Reward from the quest 'It's Dangerous to Go Alone' - pick it over the other choices. In Un'Goro Crater.",zone="Un'Goro Crater",questName="It's Dangerous to Go Alone",lore="I finally remember now... I did come here to fight Blazerunner. I was on a journey, and this was to be the last step. But I am no longer the hero..."},
