    [15397]={name="Oakthrush Staff",quality=2,ilvl=14,sourceType="quest_reward",instructions="Reward from the quest 'The Fragments Within' - pick it over the other choices. In Darkshore.",zone="Darkshore",questName="The Fragments Within",lore="The moonwell water has revealed that embedded inside the crystal are a few small fragments of bone, as well as half of a jawbone."},
    [15399]={name="Dryweed Belt",quality=2,ilvl=14,sourceType="quest_reward",instructions="Reward from the quest 'Washed Ashore' - pick it over the other choices. In Darkshore.",zone="Darkshore",questName="Washed Ashore",lore="That beached creature is not an isolated incident here in Darkshore. There are more along the coastline and even in the water."},
    [15403]={name="Ridgeback Bracers",quality=2,ilvl=18,sourceType="quest_reward",instructions="Reward from the quest 'WANTED: Murkdeep!' - pick it over the other choices. In Darkshore.",zone="Darkshore",questName="WANTED: Murkdeep!",lore="Attention! A reward is being offered for the death of the murloc \"Murkdeep\"."},
    [15411]={name="Mark of Fordring",quality=3,ilvl=63,sourceType="quest_reward",instructions="Reward from the quest 'In Dreams' - pick it over the other choices. In Western Plaguelands.",zone="Western Plaguelands",questName="In Dreams",lore="For so long, I have been a puppet of the Grand Crusader. What reason was there to fight against what the Scarlet Crusade had become?"},
