    [15468]={name="Windsong Drape",quality=2,ilvl=29,sourceType="quest_reward",instructions="Reward from the quest 'Free at Last' - pick it over the other choices. In Thousand Needles.",zone="Thousand Needles",questName="Free at Last",lore="Arnak thinks we're going to be married... but after I declined his offer he came back that night and kidnapped me. My brother tried to stop him, but Arnak was too strong."},
    [15501]={name="Outrunner's Cloak",quality=2,ilvl=17,reqLevel=12,sourceType="world_drop",instructions="World drop - drops from 376 creature types around level 11-18. Also found on the auction house."},
    [15526]={name="Sentry's Cape",quality=2,ilvl=24,reqLevel=19,sourceType="world_drop",instructions="World drop - drops from 363 creature types around level 19-26. Also found on the auction house."},
    [15689]={name="Trader's Ring",quality=2,ilvl=35,sourceType="quest_reward",instructions="Reward from the quest 'Bodyguard for Hire'. In Desolace.",zone="Desolace",questName="Bodyguard for Hire",lore="Under normal circumstances, Rigger and I would lead our kodo past the Kolkar Centaur. Every now and then we hear the Centaur war drums, and when we hear those we stop."},
    [15690]={name="Kodobone Necklace",quality=2,ilvl=41,sourceType="quest_reward",instructions="Reward from the quest 'Bone Collector'. In Desolace.",zone="Desolace",questName="Bone Collector",lore="We're sitting on a goldmine here, I tell you - a goldmine! Kodo bones will change the world forever... I have customers making furniture, music instruments, and even blasting powder out of them."},
    [15702]={name="Chemist's Ring",quality=2,ilvl=55,sourceType="quest_reward",instructions="Reward from the quest 'Melding of Influences' - pick it over the other choices. In Undercity.",zone="Undercity",questName="Melding of Influences",lore="Here is some encased ooze created from the Felwood samples you recovered. Take the case to Un'Goro Crater and find a pure ooze... the primal variety will do nicely."},
    [15703]={name="Chemist's Smock",quality=2,ilvl=55,sourceType="quest_reward",instructions="Reward from the quest 'Melding of Influences' - pick it over the other choices. In Undercity.",zone="Undercity",questName="Melding of Influences",lore="Here is some encased ooze created from the Felwood samples you recovered. Take the case to Un'Goro Crater and find a pure ooze... the primal variety will do nicely."},
    [15707]={name="Brantwood Sash",quality=2,ilvl=58,sourceType="quest_reward",instructions="Reward from the quest 'A Final Blow' - pick it over the other choices. In Felwood.",zone="Felwood",questName="A Final Blow",lore="Unfortunately, I see the only way to stop this threat to Felwood is a frontal attack. There are no other ways into Shadow Hold, and I have no means to teleport you inside."},
    [15789]={name="Deep River Cloak",quality=2,ilvl=56,sourceType="quest_reward",instructions="Reward from the quest 'Strange Sources'. In Winterspring.",zone="Winterspring",questName="Strange Sources",lore="To tell you the truth, although there are no volcanoes here in Winterspring, I believe that there are far more threatening reasons for these hot springs..."},
    [15822]={name="Shadowskin Spaulders",quality=2,ilvl=55,sourceType="quest_reward",instructions="Reward from the quest 'Runecloth' - pick it over the other choices. In Timbermaw Hold.",zone="Timbermaw Hold",questName="Runecloth",lore="In Timbermaw, we are content. We do not like strangers. This is good for us, but it is bad for trade. Not long ago, a rare night elf friend came to Timbermaw and she wore a runecloth cloak."},
    [15855]={name="Ring of Protection",quality=3,ilvl=60,sourceType="quest_reward",instructions="Reward from the quest 'Hidden Treasures'. In Eastern Plaguelands.",zone="Eastern Plaguelands",questName="Hidden Treasures",lore="Daddy told me to give you this key. He said it opens a chest out back behind the house. He also wanted me to thank you. Did you do a favor for him?"},
