    [19106]={name="Ice Barbed Spear",quality=3,ilvl=63,sourceType="quest_reward",instructions="Reward from the quest 'The Legend of Korrak' - pick it over the other choices. In Alterac Valley.",zone="Alterac Valley",questName="The Legend of Korrak",lore="The invading Stormpike are not the only threat in the region, soldier. The war in the Valley is waged on two fronts. The cannibal Winterax trolls also vie for power."},
