    [19115]={name="Flask of Forest Mojo",quality=2,ilvl=51,sourceType="quest_reward",instructions="Reward from the quest 'Return to Primal Torntusk' - pick it over the other choices. In The Hinterlands.",zone="The Hinterlands",questName="Return to Primal Torntusk",lore="Return to my mate, Primal Torntusk at Revantusk Village. Tell her that I am coming home! She is sure to reward you."},
    [19116]={name="Greenleaf Handwraps",quality=2,ilvl=50,sourceType="quest_reward",instructions="Reward from the quest 'Separation Anxiety' - pick it over the other choices. In The Hinterlands.",zone="The Hinterlands",questName="Separation Anxiety",lore="Like many in our village, I too have lost a loved one to the wilds. Alas, it was my twin brother Malkhor - taken in the same raid as Torntusk's mate by the Vilebranch."},
    [19120]={name="Rune of the Guard Captain",quality=2,ilvl=51,sourceType="quest_reward",instructions="Reward from the quest 'Job Opening: Guard Captain of Revantusk Village'. In The Hinterlands.",zone="The Hinterlands",questName="Job Opening: Guard Captain of Revantusk Village",lore="With the loss of Guard Captain Malkhor, the position of Guard Captain of Revantusk is once again open."},
    [19121]={name="Deep Woodlands Cloak",quality=3,ilvl=51,sourceType="quest_reward",instructions="Reward from the quest 'Wanted: Vile Priestess Hexx and Her Minions' - pick it over the other choices. In The Hinterlands.",zone="The Hinterlands",questName="Wanted: Vile Priestess Hexx and Her Minions",lore="By order of Primal Torntusk, Vile Priestess Hexx and her minions are to be brought to justice! A grand reward is offered for any that slay the Vile Priestess Hexx and all of her Aman'zasi elite guard."},
    [19127]={name="Charred Leather Tunic",quality=2,ilvl=50,sourceType="quest_reward",instructions="Reward from the quest 'WANTED: Overseer Maltorius' - pick it over the other choices. In Searing Gorge.",zone="Searing Gorge",questName="WANTED: Overseer Maltorius",lore="By order o' 'is eminence, Overseer Oilfist, the rogue Thorium Brotherhood agent an' newly hired commander o' the Dark Iron Slag Pit crew o' the Cauldron, Overseer Maltorius, is to be killed an' 'is head brung back as proof o' the deed."},
